using BC.FixedAsset.Services;using System;using System.Web.UI.WebControls;namespace BC.FixedAsset.Web.FixedAsset.Review{public partial class ManagerReview:SecurePage{protected GridView gridReview;protected TextBox txtReason;protected HiddenField hidReturnId,hidApproveId;protected Button btnReturn,btnApprove;protected Label lblMessage;private readonly AssetSurveyService service=new AssetSurveyService();protected void Page_Load(object s,EventArgs e){if(!IsPostBack)Bind();}private void Bind(){gridReview.DataSource=service.Search("","ManagerReview",AssetAccess,"ManagerReview");gridReview.DataBind();}protected void Approve_Click(object s,EventArgs e){try{long id;if(!long.TryParse(hidApproveId.Value,out id))throw new ArgumentException("ไม่พบรายการสำหรับอนุมัติ");service.Approve(id,AssetAccess);hidApproveId.Value="";Bind();lblMessage.Text="อนุมัติเรียบร้อย";}catch(Exception ex){lblMessage.Text=Server.HtmlEncode(ex.Message);ClientScript.RegisterStartupScript(GetType(),"approveDialog","document.getElementById('approveDialog').hidden=false;",true);}}protected void Return_Click(object s,EventArgs e){try{long id;if(!long.TryParse(hidReturnId.Value,out id)||string.IsNullOrWhiteSpace(txtReason.Text))throw new ArgumentException("กรุณาระบุเหตุผลสำหรับ Return");service.Return(id,txtReason.Text.Trim(),AssetAccess);hidReturnId.Value="";txtReason.Text="";Bind();lblMessage.Text="Return เรียบร้อย";}catch(Exception ex){lblMessage.Text=Server.HtmlEncode(ex.Message);ClientScript.RegisterStartupScript(GetType(),"returnDialog","document.getElementById('returnDialog').hidden=false;",true);}}}}
